const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],num=n=>n.toLocaleString('fa-IR');
const products=[{id:1,name:'پروتئین وی ایزوله شکلات',en:'WHEY CLUB / PURE ISOLATE',type:'isolate',flavor:'chocolate',flavorName:'شکلات',color:'lime',price:2890000,old:3200000,protein:27,size:'۱۸۰۰ گرم',popular:true},{id:2,name:'پروتئین وی کنسانتره وانیل',en:'WHEY CLUB / DAILY WHEY',type:'concentrate',flavor:'vanilla',flavorName:'وانیل',color:'cream',price:1790000,old:0,protein:24,size:'۱۰۰۰ گرم',popular:true},{id:3,name:'پروتئین وی ایزوله توت‌فرنگی',en:'WHEY CLUB / PURE ISOLATE',type:'isolate',flavor:'strawberry',flavorName:'توت‌فرنگی',color:'pink',price:2990000,old:3350000,protein:27,size:'۱۸۰۰ گرم',popular:false},{id:4,name:'پروتئین وی ترکیبی شکلات',en:'WHEY CLUB / WHEY BLEND',type:'blend',flavor:'chocolate',flavorName:'شکلات',color:'brown',price:2190000,old:2450000,protein:25,size:'۲۰۰۰ گرم',popular:true},{id:5,name:'پروتئین وی کنسانتره قهوه',en:'WHEY CLUB / DAILY WHEY',type:'concentrate',flavor:'coffee',flavorName:'قهوه',color:'coffee',price:1890000,old:0,protein:24,size:'۱۰۰۰ گرم',popular:false},{id:6,name:'پروتئین وی ایزوله وانیل',en:'WHEY CLUB / PURE ISOLATE',type:'isolate',flavor:'vanilla',flavorName:'وانیل',color:'white',price:3090000,old:0,protein:27,size:'۱۸۰۰ گرم',popular:false}];
let tab='all',cart={};try{const saved=JSON.parse(localStorage.getItem('wheyclub-cart')||'{}');for(const p of products)if(Number.isInteger(saved[p.id])&&saved[p.id]>0)cart[p.id]=Math.min(saved[p.id],99)}catch{};
function render(){const types=$$('input[name=type]:checked').map(x=>x.value),flavors=$$('input[name=flavor]:checked').map(x=>x.value),q=$('#search').value.trim().toLowerCase();let list=products.filter(p=>(!types.length||types.includes(p.type))&&(!flavors.length||flavors.includes(p.flavor))&&p.price<=Number($('#price').value)&&(p.name+' '+p.en).toLowerCase().includes(q)&&(tab!=='popular'||p.popular)&&(tab!=='sale'||p.old));const sort=$('#sort').value;if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);if(sort==='protein')list.sort((a,b)=>b.protein-a.protein);$('#priceValue').textContent=num(Number($('#price').value));$('#resultCount').textContent=num(list.length)+' محصول برای انتخاب شما';$('#empty').hidden=!!list.length;$('#grid').innerHTML=list.map(p=>`<article class="card"><button class="visual" data-detail="${p.id}" aria-label="مشاهده ${p.name}">${p.old?`<span class="badge">${num(Math.round((1-p.price/p.old)*100))}٪ تخفیف</span>`:p.popular?'<span class="badge neutral">انتخاب روزانه</span>':''}<img src="assets/${p.color}.svg" alt="${p.name}" loading="lazy"></button><div class="info"><div class="brand">${p.en}</div><button class="title" data-detail="${p.id}">${p.name}</button><div class="meta">${p.size} <span>·</span> طعم ${p.flavorName}</div><div class="nutrition"><span>${num(p.protein)} گرم پروتئین</span><span>در هر سروینگ نمونه</span></div><div class="card-bottom"><div class="price"><span class="old">${p.old?num(p.old):''}</span>${num(p.price)} <small>تومان</small></div><button class="add" data-add="${p.id}" aria-label="افزودن ${p.name} به سبد">+</button></div></div></article>`).join('')}
function reset(){tab='all';$$('aside input[type=checkbox]').forEach(x=>x.checked=false);$('#price').value=4000000;$('#search').value='';$('#sort').value='featured';$$('[data-tab]').forEach(x=>x.classList.toggle('selected',x.dataset.tab==='all'));render()}
function updateCart(){const count=Object.values(cart).reduce((a,b)=>a+b,0);$('#cartCount').textContent=num(count);try{localStorage.setItem('wheyclub-cart',JSON.stringify(cart))}catch{}const items=products.filter(p=>cart[p.id]);$('#cartItems').innerHTML=items.length?items.map(p=>`<div class="cart-row"><img src="assets/${p.color}.svg" alt="${p.name}"><div><h3>${p.name}</h3><p>${num(p.price)} تومان · ${p.size}</p></div><div class="quantity"><button data-change="${p.id}" data-delta="-1" aria-label="کاهش تعداد">−</button><span>${num(cart[p.id])}</span><button data-change="${p.id}" data-delta="1" aria-label="افزایش تعداد">+</button></div></div>`).join(''):'<p class="cart-empty">سبدت منتظر اولین انتخابته.<br>از محصولات، پروتئین مورد علاقه‌ات رو اضافه کن.</p>';$('#cartSummary').innerHTML=items.length?`<div class="total"><span>جمع سبد خرید</span><span>${num(items.reduce((s,p)=>s+p.price*cart[p.id],0))} تومان</span></div><div class="checkout-note">این یک فروشگاه نمایشی است. پرداخت و ثبت سفارش واقعی هنوز فعال نیست. محصولات، ترکیبات و قیمت‌ها نمونه هستند.</div>`:''}
let toastTimer;function add(id){cart[id]=Math.min((cart[id]||0)+1,99);updateCart();$('#toast').textContent='به سبد خرید اضافه شد ✓';$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
function detail(id){const p=products.find(x=>x.id===id);$('#productDetail').innerHTML=`<div class="detail"><img src="assets/${p.color}.svg" alt="${p.name}"><div><div class="kicker">${p.en}</div><h2>${p.name}</h2><p>${p.size} · طعم ${p.flavorName}<br>${num(p.protein)} گرم پروتئین در سروینگ نمونه</p><p>برای تکمیل پروتئین روزانه در کنار تغذیه متنوع و برنامه تمرینی.</p><div class="price">${num(p.price)} <small>تومان</small></div><button class="primary" data-add="${p.id}">افزودن به سبد خرید +</button><p class="note">محصول نمایشی؛ مشخصات و قیمت‌ها نمونه هستند. حاوی مشتقات شیر است.</p></div></div>`;$('#productDialog').showModal()}
document.addEventListener('click',e=>{const a=e.target.closest('[data-add]'),d=e.target.closest('[data-detail]'),c=e.target.closest('[data-change]'),t=e.target.closest('[data-tab]'),type=e.target.closest('[data-type]');if(a)add(Number(a.dataset.add));if(d)detail(Number(d.dataset.detail));if(c){const id=c.dataset.change;cart[id]=Math.max(0,Math.min(99,cart[id]+Number(c.dataset.delta)));if(!cart[id])delete cart[id];updateCart()}if(t){tab=t.dataset.tab;$$('[data-tab]').forEach(x=>x.classList.toggle('selected',x===t));render()}if(type){reset();$(`input[name=type][value=${type.dataset.type}]`).checked=true;render();$('#products').scrollIntoView({behavior:'smooth'})}if(e.target.closest('.close'))e.target.closest('dialog').close()});$('#search').addEventListener('input',render);$$('aside input').forEach(x=>x.addEventListener('input',render));$('#sort').addEventListener('change',render);$('#reset').onclick=reset;$('#emptyReset').onclick=reset;$('#cartOpen').onclick=()=>{updateCart();$('#cartDialog').showModal()};$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));render();updateCart();

// Only published summaries are exposed; the private queue is never fetched.
fetch('/blog/articles.json',{cache:'no-cache'}).then(r=>{if(!r.ok)throw new Error('Journal not published');return r.json()}).then(items=>{const el=document.querySelector('#latestArticles');if(!el||!items.length)return;const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));el.innerHTML=items.slice(0,3).map(a=>`<a class="editorial-card" href="${safe(a.url)}"><div class="editorial-art art-${Number(a.id)%4}"><span>WHEY CLUB JOURNAL</span><b>${String(a.id).padStart(2,'0')}</b><i>↗</i></div><div class="editorial-body"><div class="article-category">${safe(a.category)}<span>حدود ۲ دقیقه مطالعه</span></div><h2>${safe(a.title)}</h2><p>${safe(a.description)}</p><div class="read-link"><span>مطالعه مقاله ←</span></div></div></a>`).join('')}).catch(()=>{});
